import { NextResponse } from 'next/server';
export async function POST(req) {
  try {
    const d = await req.json();
    let url = 'https://n8n.mrstac.com/webhook/vinapp';
    if (d.type === 'towing') url = 'https://n8n.mrstac.com/webhook/towing';
    if (d.type === 'catalyst_quote') url = 'https://n8n.mrstac.com/webhook/catalyst';
    await fetch(url, { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(d) });
    return NextResponse.json({ success: true });
  } catch (e) { return NextResponse.json({ error: 'err' }, { status: 500 }); }
}
